# No.301-400  例文チャンク
DATA = {
"301": {"ex": "My idea of a modern kitchen is a machine that makes coffee while I heroically continue to sleep.", "tr": "俺にとって現代的な台所とは、俺が英雄的に眠り続ける間にコーヒーを淹れてくれる機械のことだ。"},
"302": {"ex": "【形】He gave me directions using an ancient landmark that had been demolished long before I was even born.<br>【名】The museum guide called the vase an ancient, and my clumsy elbow nearly turned it into an ancient tragedy.", "tr": "【形】彼は、俺が生まれるずっと前に取り壊された古代の目印を使って道案内をした。<br>【名】館長はその壺を古代の遺物と呼び、俺の不器用な肘はそれを危うく古代の悲劇に変えかけた。"},
"303": {"ex": "I promised to spend less this month, then spent an entire afternoon buying things to help me save money.", "tr": "今月は出費を抑えると誓ったのに、俺は節約を助ける品々を買うのに午後まるまる費やした。"},
"304": {"ex": "【動】The airline delayed my flight so many times that I started to consider the airport my legal residence.<br>【名】The only thing longer than the delay was the announcer's cheerful apology, repeated every fifteen minutes.", "tr": "【動】航空会社が便を何度も遅延させたので、俺は空港を法的な住所と考え始めた。<br>【名】遅延より長かったのは、十五分ごとに繰り返されるアナウンスの陽気な謝罪だけだった。"},
"305": {"ex": "I let my friend borrow my favorite pen three years ago, and I still quietly mourn its loss to this day.", "tr": "三年前に友人にお気に入りのペンを貸したが、俺は今なお静かにその喪失を悼んでいる。"},
"306": {"ex": "I would happily lend you money, but my wallet and I have a strict policy against making optimistic promises.", "tr": "喜んで金を貸したいところだが、俺の財布と俺は、楽観的な約束をしない厳格な方針を掲げている。"},
"307": {"ex": "【動】We rent a tiny apartment so expensive that the closet politely charges us extra just to store our regrets.<br>【名】The monthly rent goes up every year, unlike my salary, which prefers a peaceful and motionless existence.", "tr": "【動】我々はあまりに高い狭いアパートを借りていて、押し入れは後悔を仕舞うだけで丁重に追加料金を取る。<br>【名】家賃は毎年上がる。平穏で微動だにしない生活を好む俺の給料とは違って。"},
"308": {"ex": "The hotel promised to provide everything, then provided a single towel and the phone number of a distant help desk.", "tr": "ホテルは何もかも提供すると約束し、それからタオル一枚と、遠く離れたヘルプデスクの電話番号を提供した。"},
"309": {"ex": "【名】He pinned his brilliant plan to the board, and the board immediately became the smartest object in the room.<br>【動】We board the plane last, get the worst seats, and then act genuinely surprised, as if this were somehow new.", "tr": "【名】彼は名案を掲示板に貼り、掲示板は即座に部屋で一番賢い物体になった。<br>【動】我々は最後に搭乗し、最悪の席に座り、そしてまるで初めてのように、心底驚いたふりをする。"},
"310": {"ex": "I told myself I would clean out the garbage this weekend, a beautiful promise I make roughly every single weekend.", "tr": "今週末こそゴミを片づけると自分に言い聞かせた。おおよそ毎週末する、美しい約束だ。"},
"311": {"ex": "The most expensive item on the menu was the tap water, priced as though it had been personally blessed by a saint.", "tr": "メニューで一番高い品は水道水で、まるで聖人が個人的に祝福したかのような値段がついていた。"},
"312": {"ex": "【名】The shopping cart had one broken wheel that insisted, with great passion, on steering us toward the wine aisle.<br>【動】He wheeled the enormous suitcase through the airport as if it contained the last hopes of an entire nation.", "tr": "【名】ショッピングカートには壊れた車輪が一つあり、大いなる情熱をもって我々をワイン売り場へ導こうとした。<br>【動】彼は巨大なスーツケースを、まるで一国の最後の希望が入っているかのように空港で押していった。"},
"313": {"ex": "【名】She left me a sweet note on the fridge that turned out to be a detailed list of chores I owed her.<br>【動】Please note that I did read your long message; I simply chose emotional survival over an immediate reply.", "tr": "【名】彼女は冷蔵庫に優しいメモを残してくれたが、それは俺が負っている家事の詳細な一覧だった。<br>【動】あなたの長文は確かに読んだと留意してほしい。俺はただ即答より心の生存を選んだだけだ。"},
"314": {"ex": "【名】He gave me a birthday present so useless that even the wrapping paper looked mildly embarrassed about it.<br>【形】All members were present at the meeting, except for the one person whose ideas we actually needed.<br>【動】She presented her excuse with such confidence that we nearly gave her an award instead of a warning.", "tr": "【名】彼は俺の誕生日に、包装紙すら少し気まずそうに見えるほど役に立たないプレゼントをくれた。<br>【形】会議には全員が出席していた。我々が本当に必要としたアイデアを持つ唯一の人物を除いて。<br>【動】彼女があまりに自信たっぷりに言い訳を提示したので、我々は警告の代わりに賞を与えかけた。"},
"315": {"ex": "【名】I found a real bargain on shoes, saving twenty dollars while somehow spending two hundred on things I didn't need.<br>【動】He tried to bargain with the vending machine, which responded with the cold indifference of true authority.", "tr": "【名】靴で本物のお買い得品を見つけ、二十ドル節約しながら、なぜか要らない物に二百ドル使った。<br>【動】彼は自販機と値切り交渉を試みたが、自販機は真の権威者らしい冷たい無関心で応じた。"},
"316": {"ex": "【名】My closet is full of stuff I am absolutely certain I will need on some vague and glorious future occasion.<br>【動】He stuffed his suitcase so full that closing it became a two-person job and a genuine test of friendship.", "tr": "【名】俺のクローゼットは、いつか漠然と輝かしい未来の機会に必ず必要になると確信している物で満杯だ。<br>【動】彼はスーツケースをあまりに詰め込んだので、閉めるのは二人がかりの仕事、真の友情の試練となった。"},
"317": {"ex": "【名】He tied the gift with a single string, presenting it as if fine craftsmanship were entirely beneath him.<br>【動】She strung together three unrelated excuses so smoothly that even I started to believe she had been abducted.", "tr": "【名】彼は贈り物を紐一本で縛り、まるで丁寧な仕事など自分には無用とばかりに差し出した。<br>【動】彼女は無関係な言い訳三つをあまりに滑らかに繋いだので、俺すら彼女が誘拐されたと信じかけた。"},
"318": {"ex": "【名】I planned to use my leisure to learn a language, and instead I mastered the art of lying very still on the sofa.<br>【形】He wore leisure clothes to the formal dinner and insisted, with a straight face, that comfort is the true elegance.", "tr": "【名】余暇を語学の勉強に使う予定だったが、代わりに俺はソファでじっと横たわる技を極めた。<br>【形】彼は正式な晩餐に普段着を着てきて、真顔で、快適さこそ真の優雅さだと言い張った。"},
"319": {"ex": "【名】I started a strict diet on Monday, and by lunchtime the diet had already quietly submitted its resignation.<br>【動】He decided to diet before the holidays, an ambition that lasted precisely until the first plate of cookies.", "tr": "【名】月曜に厳しいダイエットを始めたが、昼までにそのダイエットはすでに静かに辞表を提出していた。<br>【動】彼は休暇前に減量すると決めたが、その志は最初のクッキーの皿までしか正確にはもたなかった。"},
"320": {"ex": "We bought the furniture that required assembly, and now the living room contains a chair and a permanent grudge.", "tr": "我々は組み立て式の家具を買い、今やリビングには椅子一脚と、永遠の恨みが置かれている。"},
"321": {"ex": "My refrigerator is where good vegetables go to slowly transform into a science experiment I never agreed to fund.", "tr": "うちの冷蔵庫は、良い野菜が、俺が出資に同意した覚えのない科学実験へとゆっくり変わっていく場所だ。"},
"322": {"ex": "The traffic was so bad that I finished an entire audiobook and still had not reached the end of my own street.", "tr": "渋滞があまりにひどく、俺はオーディオブックを一冊まるまる聴き終えても、まだ自分の通りの端にすら着いていなかった。"},
"323": {"ex": "They say you should never sell yourself short, so I confidently sold myself at a very generous imaginary price.", "tr": "自分を安売りするなと言うので、俺は自信満々に、非常に気前のいい架空の値段で自分を売り込んだ。"},
"324": {"ex": "【動】I offered to pay for dinner, secretly praying my friend would insist, which he did not, with terrifying speed.<br>【名】The pay was modest, but the free snacks in the break room did their best to compensate for my crushed dreams.", "tr": "【動】俺は夕食を奢ると申し出て、友人が固辞するよう密かに祈ったが、彼は恐ろしい速さでそうしなかった。<br>【名】給料は控えめだったが、休憩室の無料の菓子が、砕けた俺の夢を埋め合わせようと最善を尽くした。"},
"325": {"ex": "【動】I wear the same three outfits and rotate them with the quiet confidence of a man with far bigger problems.<br>【名】This old sweater is not fashion; it is simply comfortable wear that I refuse to surrender to the passage of time.", "tr": "【動】俺は同じ三着を着回し、もっと大きな問題を抱えた男の静かな自信をもってローテーションしている。<br>【名】この古いセーターはファッションではなく、時の流れに明け渡すのを拒む、ただ快適な衣服だ。"},
"326": {"ex": "I own many clothes, yet I still stand before the closet every morning declaring, with deep conviction, that I have nothing.", "tr": "服はたくさん持っているのに、俺は毎朝クローゼットの前に立ち、深い確信を込めて、着る物がないと宣言する。"},
"327": {"ex": "He promised to marry his job, and honestly the job responds to his messages far faster than any human ever has.", "tr": "彼は自分の仕事と結婚すると誓ったが、正直、仕事は人間の誰よりずっと早く彼のメッセージに返信する。"},
"328": {"ex": "My cat greets me at the door every evening, though I strongly suspect it is greeting the food, not me personally.", "tr": "うちの猫は毎晩玄関で俺を出迎えるが、俺自身ではなく餌を出迎えているのだと強く疑っている。"},
"329": {"ex": "【名】The waiter brought the wrong order, and it was, humiliatingly, far better than the thing I had actually chosen.<br>【動】I ordered a small coffee, and the barista returned with a cup so large it required both hands and a strategy.", "tr": "【名】ウェイターが違う注文を持ってきたが、それは屈辱的なことに、俺が実際に選んだものよりずっと美味かった。<br>【動】小さいコーヒーを注文したのに、バリスタは両手と戦略を要するほど巨大なカップを持って戻ってきた。"},
"330": {"ex": "【名】My room is not messy; it is a carefully curated exhibition of everything I have avoided dealing with this year.<br>【動】We could not room together on the trip, because his snoring qualifies, scientifically, as a natural disaster.", "tr": "【名】俺の部屋は散らかっているのではない。今年向き合うのを避けてきた全てを丁寧に構成した展示なのだ。<br>【動】旅行で彼と相部屋にはできなかった。彼のいびきは科学的に自然災害に分類されるからだ。"},
"331": {"ex": "He told a long story about his weekend that had no plot, no point, and yet somehow refused to ever actually end.", "tr": "彼は週末についての長い話をしたが、筋も要点もなく、それでいてなぜか決して終わろうとしなかった。"},
"332": {"ex": "The construction site next door starts drilling at dawn, ensuring my alarm clock has been permanently made redundant.", "tr": "隣の工事現場は夜明けに掘削を始め、おかげで俺の目覚まし時計は永久に不要になった。"},
"333": {"ex": "I mowed the entire back yard yesterday, and today the grass has already returned, looking faintly amused by my effort.", "tr": "昨日、裏庭を全部刈ったのに、今日にはもう草が戻ってきて、俺の努力をかすかに面白がっているように見える。"},
"334": {"ex": "【名】I finally reached the bottom of my to-do list, only to discover a second, secret list hiding shyly beneath it.<br>【形】I always draw the bottom bunk in life, both literally at camp and figuratively in every group project ever.", "tr": "【名】ついてTodoリストの一番下に到達したら、その下に恥ずかしそうに隠れる二枚目の秘密のリストを発見した。<br>【形】俺は人生でいつも一番下の段を引く。キャンプでも文字通り、あらゆるグループ課題でも比喩的に。"},
"335": {"ex": "【名】I waited in the wrong line for forty minutes with the calm dignity of a man too proud to ever check the sign.<br>【動】They lined the hallway with motivational posters, which somehow only deepened everyone's collective sense of doom.", "tr": "【名】俺は看板を確認できないほど誇り高い男の静かな威厳をもって、四十分間も間違った列に並んだ。<br>【動】彼らは廊下に激励のポスターを並べたが、なぜかそれは皆の集合的な絶望感を深めるだけだった。"},
"336": {"ex": "【名】I sat in the back row so I could nod thoughtfully while secretly planning my dinner in exhaustive detail.<br>【動】The tourists tried to row the little boat in a perfect circle, achieving a level of chaos usually reserved for legends.", "tr": "【名】俺は後ろの列に座り、思慮深くうなずきながら、密かに夕食を事細かに計画できるようにした。<br>【動】観光客たちは小舟を綺麗な円で漕ごうとし、伝説級の混沌を成し遂げた。"},
"337": {"ex": "He has an impressive academic background, yet still cannot figure out how to make the office printer stop weeping ink.", "tr": "彼は立派な学歴を持つが、それでもオフィスのプリンターがインクを泣き流すのを止める方法はわからない。"},
"338": {"ex": "I have a terrible sense of direction, so I confidently followed the crowd and ended up at a stranger's wedding.", "tr": "俺は方向感覚が壊滅的なので、自信満々に人混みについていき、見知らぬ人の結婚式にたどり着いた。"},
"339": {"ex": "【名】Office culture here means pretending to enjoy the mandatory fun until the mandatory fun mercifully ends.<br>【動】She cultured a friendship with the boss so carefully that even her houseplants seemed jealous of the dedication.", "tr": "【名】ここの社風とは、義務的な楽しみが慈悲深く終わるまで、それを楽しむふりをすることを意味する。<br>【動】彼女は上司との友情をあまりに念入りに育てたので、彼女の観葉植物すらその献身に嫉妬しているようだった。"},
"340": {"ex": "My attempt at abstract art was so confusing that the gallery mistook it for a very expensive genuine masterpiece.", "tr": "俺の抽象芸術の試みはあまりに難解だったので、画廊はそれを非常に高価な本物の傑作と勘違いした。"},
"341": {"ex": "I still watch cartoons on Saturday mornings, and I will defend this sacred ritual against absolutely anyone who dares.", "tr": "俺は今も土曜の朝にアニメを見ていて、あえて挑む者が誰であろうと、この神聖な儀式を守り抜く。"},
"342": {"ex": "【名】I bought a thick novel to look intellectual on the train and have been on the same page for three weeks.<br>【形】He proposed a novel solution to the leak, which was, in essence, to place a bucket and simply believe in it deeply.", "tr": "【名】電車で知的に見せようと分厚い小説を買ったが、俺は三週間ずっと同じページにいる。<br>【形】彼は水漏れに斬新な解決策を提案した。要はバケツを置き、それを深く信じるというものだった。"},
"343": {"ex": "I bought an expensive musical instrument to become cultured, and now it functions as a very artistic and dusty coat rack.", "tr": "教養を身につけようと高価な楽器を買ったが、今やそれは非常に芸術的で埃をかぶったコート掛けとして機能している。"},
"344": {"ex": "【名】He hummed a cheerful tune all morning, blissfully unaware that it was slowly driving the entire office to madness.<br>【動】I finally tuned the old guitar, and it now sounds only slightly like a cat expressing deep personal grievances.", "tr": "【名】彼は一日中陽気な曲を口ずさみ、それがオフィス全体を徐々に狂気へ追いやっていることに幸せなほど無自覚だった。<br>【動】ついに古いギターを調律したが、今や個人的な深い不満を訴える猫に、ほんの少しだけ似た音がする。"},
"345": {"ex": "【名】He wrote me a text so long that it was less a sentence and more a formal declaration of emotional independence.<br>【動】The judge sentenced him to community service, and he served it by loudly narrating everyone else's minor mistakes.", "tr": "【名】彼は俺に、文というより感情的独立の正式な宣言と呼ぶべき長さのメッセージを書いてきた。<br>【動】裁判官は彼に社会奉仕を言い渡し、彼は他人の些細なミスを大声で実況することでそれを果たした。"},
"346": {"ex": "I read one online article about health and now confidently diagnose all my friends with conditions I cannot even pronounce.", "tr": "健康についてのネット記事を一本読んだだけで、俺は今や自信満々に、発音すらできない病名を友人全員に診断している。"},
"347": {"ex": "The exam passage was so dense that by the third sentence I had forgotten my own name and the general concept of reading.", "tr": "試験の長文はあまりに難解で、三文目までに俺は自分の名前と、読むという概念そのものを忘れていた。"},
"348": {"ex": "My professional vocabulary consists entirely of nodding slowly and saying \"let's circle back on that\" with great authority.", "tr": "俺のビジネス語彙は、ゆっくりうなずき、大いなる権威をもって「その件は後で戻りましょう」と言うことだけで成り立っている。"},
"349": {"ex": "【名】A rumor spread that the office was getting free coffee, and productivity briefly reached historically unheard-of levels.<br>【動】It is rumored that our manager once smiled in 2019, though no living witness has ever come forward to confirm it.", "tr": "【名】オフィスに無料コーヒーが来るという噂が広まり、生産性は一時的に歴史上前例のない水準に達した。<br>【動】うちの課長は二〇一九年に一度微笑んだと噂されるが、それを確認する生存者は一人も名乗り出ていない。"},
"350": {"ex": "【動】I can spell every difficult word perfectly until someone watches me, at which point my hands forget the alphabet entirely.<br>【名】He cast a spell of boredom over the meeting so complete that three people fell asleep with their eyes bravely open.", "tr": "【動】俺は難しい単語を全部完璧に綴れる。誰かが見ていない限りは。見られた途端、俺の手はアルファベットを丸ごと忘れる。<br>【名】彼は会議に完璧な退屈の呪文をかけ、三人が勇敢にも目を開けたまま眠りに落ちた。"},
"351": {"ex": "I cannot pronounce the name of the fancy dish, so I just point at the menu and pray the waiter is a merciful person.", "tr": "その洒落た料理の名前を発音できないので、俺はただメニューを指さし、ウェイターが慈悲深い人であることを祈る。"},
"352": {"ex": "【名】The parking sign had so many confusing rules that reading it felt like decoding an ancient and vengeful curse.<br>【動】He asked me to sign the document without reading it, which is, as we all know, the beginning of every good horror story.", "tr": "【名】駐車の標識にはあまりに紛らわしい規則が多く、読むのは古代の執念深い呪いを解読するようだった。<br>【動】彼は読まずに書類にサインしてくれと頼んできた。周知のとおり、それはあらゆる良質なホラーの始まりだ。"},
"353": {"ex": "【動】I asked what the cryptic email meant, and three coworkers gave me three different, equally terrifying interpretations.<br>【形】The old shopkeeper was so mean about returns that customers preferred to simply keep the broken items and quietly move on.", "tr": "【動】その謎めいたメールの意味を尋ねたら、同僚三人が三通りの、等しく恐ろしい解釈を返してきた。<br>【形】その老店主は返品にあまりに意地悪だったので、客は壊れた品をそのまま持ち帰り、静かに諦める方を選んだ。"},
"354": {"ex": "He threatened to publish his memoir, and half the town suddenly remembered urgent business in a completely different country.", "tr": "彼が回顧録を出版すると脅したところ、町の半分が突然、まったく別の国での緊急の用事を思い出した。"},
"355": {"ex": "【動】She displayed her vacation photos with such enthusiasm that we all quietly began planning our own escape routes.<br>【名】The museum's new display was a single empty chair, which critics praised as a profound and bold statement about sitting.", "tr": "【動】彼女があまりに熱心に休暇の写真を見せびらかすので、我々は皆、静かに各自の逃走経路を計画し始めた。<br>【名】美術館の新しい展示は空の椅子一脚で、批評家はそれを「座ること」についての深遠で大胆な表現と称賛した。"},
"356": {"ex": "【動】I trust my phone's navigation completely, which is precisely why I once confidently drove into a very scenic lake.<br>【名】He earned my trust slowly over ten years and then lost it instantly by eating the last slice I had clearly labeled.", "tr": "【動】俺はスマホのナビを完全に信頼している。だからこそ一度、自信満々に景色の良い湖へ突っ込んだのだ。<br>【名】彼は十年かけてゆっくり俺の信頼を得て、俺がはっきり名前を書いた最後の一切れを食べて一瞬で失った。"},
"357": {"ex": "My weekend mood tends to depend entirely on whether I remembered to buy coffee before the stores all decided to close.", "tr": "俺の週末の機嫌は、店が全部閉まると決める前にコーヒーを買い忘れなかったかどうかに、完全に依存しがちだ。"},
"358": {"ex": "I have learned never to rely on my own memory, which treats important appointments as gentle, optional suggestions.", "tr": "俺は自分の記憶を頼りにしないことを学んだ。それは重要な予定を、優しく任意の提案として扱うからだ。"},
"359": {"ex": "Before every exam I pray to gods I have neglected all semester, which feels fair given how much I neglected the textbook.", "tr": "試験のたび、俺は一学期ずっと放っておいた神々に祈る。教科書を放っておいた分、それは公平に思える。"},
"360": {"ex": "I do not beg for help; I simply stand near capable people and radiate helplessness until someone bravely intervenes.", "tr": "俺は助けを乞わない。ただ有能な人の近くに立ち、誰かが勇敢に介入するまで無力さを放射するだけだ。"},
"361": {"ex": "I prefer to make my decisions quickly and then spend the following three weeks quietly regretting each and every one.", "tr": "俺は決断を素早く下し、その後の三週間を、一つ残らず静かに後悔して過ごす方を好む。"},
"362": {"ex": "I did not weep at the sad movie; a rare and highly specific onion allergy simply happened to strike me at that exact moment.", "tr": "俺は悲しい映画で泣いたのではない。稀で極めて特殊な玉ねぎアレルギーが、たまたまその瞬間に俺を襲っただけだ。"},
"363": {"ex": "【動】I do not hate Mondays; I simply believe they should be legally required to arrive with a formal written apology.<br>【名】His hate for slow walkers is so pure and consuming that it could probably power a small and very angry city.", "tr": "【動】俺は月曜が嫌いなのではない。ただ、正式な謝罪文を添えて到着することを法で義務づけるべきだと信じているだけだ。<br>【名】彼の遅い歩行者への憎しみはあまりに純粋で全てを飲み込むので、小さくて非常に怒った街の電力を賄えるだろう。"},
"364": {"ex": "【動】I refuse to worry about problems that have not happened yet; I prefer to worry about them intensely all at once later.<br>【名】My biggest worry is that one day I will run out of things to worry about and have to face genuine peace and quiet.", "tr": "【動】俺はまだ起きていない問題を心配するのを拒む。後でまとめて激しく心配する方を好むのだ。<br>【名】俺の最大の心配は、いつか心配の種が尽き、本物の平穏と静けさに向き合わねばならなくなることだ。"},
"365": {"ex": "I get anxious before phone calls, so I rehearse the entire conversation and then say something completely unrelated on the spot.", "tr": "俺は電話の前に不安になるので、会話全体を予行演習し、そして本番でまったく無関係なことを言う。"},
"366": {"ex": "Nothing can truly satisfy my hunger at midnight, which is precisely why I stand in front of the open fridge as a spiritual practice.", "tr": "真夜中の空腹を本当に満たせるものは何もない。だからこそ俺は精神修養として、開けた冷蔵庫の前に立つのだ。"},
"367": {"ex": "It really began to annoy me that the printer worked perfectly every single time, except during the exact moment I actually needed it.", "tr": "プリンターが毎回完璧に動くのに、俺が本当に必要な瞬間だけ動かないことが、本気で癪に障り始めた。"},
"368": {"ex": "【動】I do not want to bother you, he said, right before proceeding to bother me for the next forty-five uninterrupted minutes.<br>【名】Cooking for one person is such a bother that I now consider a bag of chips a perfectly balanced evening meal.", "tr": "【動】迷惑はかけたくないんだ、と彼は言い、その直後から四十五分間ぶっ通しで俺を煩わせ始めた。<br>【名】一人分の料理はあまりに面倒なので、俺は今やポテトチップス一袋を完璧にバランスの取れた夕食とみなしている。"},
"369": {"ex": "Please do not disturb me while I am busy, he said, doing absolutely nothing except watching videos of cats falling off tables.", "tr": "忙しいから邪魔しないでくれ、と彼は言ったが、机から落ちる猫の動画を見る以外、何一つしていなかった。"},
"370": {"ex": "The horror movie did not frighten me at all, which is exactly why I have kept every single light in the house on since then.", "tr": "そのホラー映画はまったく俺を怖がらせなかった。だからこそ俺はあれ以来、家中の明かりを一つ残らず点けたままにしている。"},
"371": {"ex": "【動】I deeply regret nothing, except every food decision, every text sent after midnight, and roughly ninety percent of my haircuts.<br>【名】My only regret is that I have but one life to spend not answering emails and pretending my phone is mysteriously broken.", "tr": "【動】俺は何一つ深く後悔していない。あらゆる食事の判断、深夜に送った全メッセージ、そして髪型の約九割を除いては。<br>【名】俺の唯一の後悔は、メールに返信せず、スマホが謎に壊れたふりをして過ごす人生が、たった一つしかないことだ。"},
"372": {"ex": "【名】He did me a small favor once and now brings it up in every conversation as if he had personally saved my entire life.<br>【動】The referee seemed to favor the other team so openly that even their own players began to feel slightly embarrassed.", "tr": "【名】彼は一度俺に小さな親切をしただけで、今やあらゆる会話で、まるで俺の人生全部を救ったかのように持ち出す。<br>【動】審判があまりに露骨に相手チームをひいきしたので、相手側の選手すら少し気まずくなり始めた。"},
"373": {"ex": "【名】I lost all interest in the hobby the exact moment it required actual effort and stopped being merely a fun idea in my head.<br>【動】The lecture failed to interest anyone, so the professor bravely turned off the lights, which finally interested us in sleep.", "tr": "【名】その趣味が実際の努力を要求し、頭の中の楽しい構想でなくなった瞬間、俺は一切の興味を失った。<br>【動】講義は誰の関心も引けなかったので、教授は勇敢に照明を消し、それがついに我々を睡眠に関心を持たせた。"},
"374": {"ex": "【名】It is a real pity that the weekend rushes by in a blur while a single Monday morning meeting can bend the very laws of time.<br>【動】Do not pity me for eating cereal for dinner; pity the cereal, which never asked to be part of my questionable life choices.", "tr": "【名】週末は霞のように過ぎ去るのに、月曜朝の会議一つが時間の法則そのものを曲げられるとは、実に残念なことだ。<br>【動】夕食にシリアルを食べる俺を憐れむな。憐れむべきはシリアルだ。俺の怪しい選択に加わることを望んでいなかったのだから。"},
"375": {"ex": "The library book was due last month, and I now avoid the entire neighborhood as if fleeing from a very calm and patient crime.", "tr": "図書館の本は先月が返却期限で、俺は今や、非常に穏やかで辛抱強い犯罪から逃れるように、その界隈全体を避けている。"},
"376": {"ex": "【名】The only reason I go to the gym is to justify the elaborate snack I have already promised myself on the drive home.<br>【動】I tried to reason with the toddler about bedtime, and I lost the debate so completely that I questioned my own education.", "tr": "【名】俺がジムに行く唯一の理由は、帰りの車ですでに自分に約束した手の込んだ軽食を正当化するためだ。<br>【動】幼児と就寝時間について理を説こうとしたが、あまりに完敗したので、俺は自分の学歴を疑った。"},
"377": {"ex": "【名】I studied all night for the exam, and the result was a deep, expert-level knowledge of one topic that was not even on it.<br>【動】Skipping breakfast to save time usually results in me making three separate emotional decisions before ten in the morning.", "tr": "【名】試験のため徹夜で勉強し、その結果、出題すらされなかった一つの話題についての深い専門的知識を得た。<br>【動】時間節約のため朝食を抜くと、たいてい午前十時までに俺は三つの別々の感情的決断を下すことになる。"},
"378": {"ex": "The motivational poster in the office had no visible effect on morale, though it did have a strong effect on my urge to laugh.", "tr": "オフィスの激励ポスターは士気に目に見える効果はなかったが、俺の笑いたい衝動には強い効果があった。"},
"379": {"ex": "【名】Peer pressure had such a strong influence on me that I once bought a plant just because everyone else confidently owned one.<br>【動】The weather can influence my entire mood, which is why a single gray cloud can quietly cancel every plan I ever made.", "tr": "【名】同調圧力の影響があまりに強く、俺は一度、皆が自信満々に持っているというだけで観葉植物を買った。<br>【動】天気は俺の気分全体を左右しうる。だから一片の灰色の雲が、俺の立てた全計画を静かに中止にできるのだ。"},
"380": {"ex": "【名】By the end of the long meeting, I had reached the end of my patience, my snacks, and my will to keep pretending to care.<br>【動】I decided to end my bad habits on Monday, a decision that has now been bravely postponed for eighty-seven consecutive Mondays.", "tr": "【名】長い会議の終わりまでに、俺は忍耐と軽食と、気にかけるふりを続ける意志の終わりに達していた。<br>【動】俺は月曜に悪癖を絶つと決めたが、その決断は今や八十七週連続で勇敢に延期されている。"},
"381": {"ex": "【名】The cause of the office argument was, as always, whose turn it was to finally replace the empty coffee pot on the counter.<br>【動】My attempt to fix the leak somehow managed to cause a second, larger leak with far more ambition than the original one.", "tr": "【名】オフィスの口論の原因は、いつものように、カウンターの空のコーヒーポットを誰が交換する番かだった。<br>【動】水漏れを直そうとした俺の試みは、なぜか元よりずっと野心的な、二つ目のより大きな水漏れを引き起こした。"},
"382": {"ex": "I pretended the bad review did not affect me, right up until I read it aloud to six different people over the following week.", "tr": "俺はその酷評が自分に影響していないふりをした。翌週にかけて六人もの人にそれを音読するまでは。"},
"383": {"ex": "【名】There is no easy way to say this, so I will take the long way, adding several dramatic pauses purely for my own enjoyment.<br>【副】The line was way too long, so I confidently declared I never wanted that coffee anyway and left with my dignity mostly intact.", "tr": "【名】これを言う簡単な方法はないので、俺は遠回りをし、ただ自分の楽しみのために劇的な間をいくつも挟むことにする。<br>【副】列がはるかに長すぎたので、俺は自信満々に、どうせそのコーヒーは要らなかったと宣言し、尊厳をほぼ保って立ち去った。"},
"384": {"ex": "He explained the rules in such a condescending manner that I briefly considered breaking every single one out of pure principle.", "tr": "彼があまりに見下した態度で規則を説明したので、俺は純粋な信念から、その一つ残らずを破ろうかと一瞬考えた。"},
"385": {"ex": "I walked into the kitchen with a clear purpose, immediately forgot it, and now stand here as a monument to human ambition.", "tr": "俺は明確な目的をもって台所に入り、即座にそれを忘れ、今や人間の野心の記念碑としてここに立っている。"},
"386": {"ex": "For the sake of peace, I agreed I was wrong, even though history, logic, and three separate witnesses were all firmly on my side.", "tr": "平和のために、俺は自分が間違っていたと認めた。歴史も論理も三人の証人も、揃って断固俺の側についていたのに。"},
"387": {"ex": "【形】I was absolutely certain I had the right directions, which is exactly how I ended up giving a tour of a stranger's driveway.<br>【副】Turn right at the corner, he said, and I did, right into an experience I will be describing to my therapist for many years.<br>【名】She fought for her right to the last slice of cake with a passion usually reserved for genuinely important historical causes.", "tr": "【形】俺は正しい道順を知っていると絶対の確信があった。だからこそ見知らぬ人の私道を案内する羽目になったのだ。<br>【副】角を右に曲がれと彼は言い、俺はそうした。まっすぐ、何年もセラピストに語ることになる体験の中へと。<br>【名】彼女は最後のケーキ一切れへの権利のため、本当に重要な歴史的大義にしか使われないような情熱で戦った。"},
"388": {"ex": "【形】My plan was a complete success, if you generously define success as everything going wrong in a surprisingly organized fashion.<br>【動】I finally decided to complete the project I abandoned last year, mostly so I could feel the pride of avoiding it all over again.", "tr": "【形】俺の計画は完全な成功だった。全てが驚くほど整然と失敗することを、成功と寛大に定義するならば。<br>【動】俺はついに去年放棄した企画を完成させると決めた。主に、また一から避ける誇りを味わえるようにだ。"},
"389": {"ex": "I could hardly stay awake during the meeting, and yet my brain chose that exact moment to replay every embarrassing thing I did in school.", "tr": "会議中ほとんど起きていられなかったのに、俺の脳はその瞬間を選んで、学生時代の恥ずかしい行いを全部再生した。"},
"390": {"ex": "I almost went to the gym today, which, in my personal accounting system, counts as a full and genuinely exhausting workout.", "tr": "俺は今日ほとんどジムに行きかけた。俺個人の会計制度では、それは本格的で真に疲れる運動一回に数えられる。"},
"391": {"ex": "The instructions were only partly translated, so I assembled the shelf based on faith, guesswork, and one very confident diagram.", "tr": "説明書は一部しか翻訳されていなかったので、俺は信仰と当てずっぽうと、やたら自信のある図解一枚を頼りに棚を組み立てた。"},
"392": {"ex": "The restaurant was, indeed, as expensive as everyone warned, and the tiny portion did indeed require a magnifying glass to locate.", "tr": "そのレストランは、確かに皆が警告したとおり高く、そのちっぽけな一皿は、確かに探すのに虫眼鏡が必要だった。"},
"393": {"ex": "【副】I read the entire report twice and still did not understand even the title, let alone a single actual sentence within it.<br>【形】The playing field was even, the referees were fair, and yet somehow our team still managed to lose to a group of amateurs.", "tr": "【副】報告書を二度も読み通したのに、俺は一文どころか、題名すら理解できなかった。<br>【形】競技場は平らで、審判は公平だった。それでもなぜか我々のチームは素人集団に負けてみせた。"},
"394": {"ex": "That is exactly what I would have said, he claimed, five full minutes after I had already said precisely that very thing myself.", "tr": "まさにそれこそ俺が言おうとしたことだ、と彼は主張した。俺がすでにまさにそれを言った、たっぷり五分後に。"},
"395": {"ex": "I gradually realized that \"I'll start tomorrow\" is not a plan but a lifestyle I have somehow committed to with quiet dedication.", "tr": "俺は徐々に、「明日から始める」は計画ではなく、なぜか静かな献身で身を捧げてきた生き方だと悟った。"},
"396": {"ex": "I forgot my umbrella; therefore, the universe logically concluded that today was the perfect day for a dramatic and cinematic downpour.", "tr": "俺は傘を忘れた。よって宇宙は論理的に、今日こそ劇的で映画のような豪雨に最適な日だと結論づけた。"},
"397": {"ex": "I planned to cook a healthy dinner but ordered pizza instead, honoring a proud tradition I have upheld with remarkable consistency.", "tr": "俺は健康的な夕食を作る予定だったが、代わりにピザを注文し、驚くべき一貫性で守り抜いてきた誇り高き伝統を重んじた。"},
"398": {"ex": "【前】I stayed awake until the exact moment I finally decided to give up, at which point my body cheerfully demanded a nap.<br>【接】I refused to leave the sofa until my show finished, and by then I had also somehow become one with the cushions.", "tr": "【前】俺は諦めると決めたまさにその瞬間まで起きていて、その途端、体は陽気に昼寝を要求した。<br>【接】番組が終わるまで俺はソファを離れるのを拒んだが、その頃には俺はなぜかクッションと一体化していた。"},
"399": {"ex": "【前】Besides forgetting my keys, my wallet, and my dignity, I would say the morning went remarkably and suspiciously smoothly.<br>【副】I have no time to exercise; besides, my remote control offers a level of loyalty that no gym membership could ever match.", "tr": "【前】鍵と財布と尊厳を忘れたこと以外は、朝は驚くほど、そして怪しいほど順調だったと言える。<br>【副】運動する時間はない。それに、俺のリモコンは、どんなジムの会員権も及ばぬ忠誠を捧げてくれる。"},
"400": {"ex": "【前】Everyone enjoyed the party except me, since I spent the entire evening bravely guarding the snack table from imaginary threats.<br>【接】I would have finished the whole assignment on time, except that my bed staged a compelling and ultimately victorious intervention.", "tr": "【前】俺以外の全員がパーティーを楽しんだ。俺は一晩中、勇敢にも空想上の脅威から軽食のテーブルを守っていたからだ。<br>【接】俺は課題を全部期限内に終えられたはずだった。ベッドが説得力ある、最終的に勝利する介入を仕掛けてこなければ。"},
}
